    this.roundMap.set('AA.Oen00272',',AA.Oen00272,Ed-U-Games tm,20070331,10,ThWrQu,LiEs,,EvQu,thomas paine;paine,,aPRA1_25 zPRA1_30,,,,,History/American/Revolution,Put the famous words of Thomas Paine in order.,,Rows=5 Cols=1 FntSize=18 FntColor=black BkGndColor=yellow LnCnt=1 SingleScreen=No Sort=No ,We have it ,in our power ,to begin ,the world ,over again.');
    this.roundMap.set('AA.Oen00273',',AA.Oen00273,Ed-U-Games tm,20070331,10,ThWrQu,LiEs,,EvQu,thomas paine;paine,,aPRA1_25 zPRA1_30,,,,,History/American/Revolution,Put the famous words of Thomas Paine in order.,,Rows=5 Cols=1 FntSize=18 FntColor=black BkGndColor=yellow LnCnt=1 SingleScreen=No Sort=No ,What we ,obtain ,too cheap` ,we esteem ,to lightly.');
